class.view-imgBox@tag.img@data-src
@js:
var pool = ['p4.nnpic.xyz','p6.nnpic.xyz','p8.nnpic.xyz','p9.nnpic.xyz','p10.nnpic.xyz','p11.nnpic.xyz'];
var bad = ['img.nnpic.xyz','p4.nnpic.xyz','p6.nnpic.xyz','p8.nnpic.xyz','p9.nnpic.xyz','p10.nnpic.xyz','p11.nnpic.xyz'];
var urls = result.split('\n').filter(Boolean);
var out = [];
for (var i = 0; i < urls.length; i++) {
  var u = urls[i];
  var m = u.match(/^https?:\/\/([^\/]+)(\/.*)$/);
  if (m && bad.indexOf(m[1]) >= 0) {
    u = 'https://' + pool[Math.floor(Math.random()*pool.length)] + m[2];
  }
  out.push('<img src="' + u + '">');
}
out.join('\n');

